/** 四项显示偏好保留编辑草稿，宿主确认后同步详情页和输入框。 */
import { useEffect, useState, useSyncExternalStore } from "react";
import { Button, Input, Switch } from "@deepseek-ai/dsh-client-ui-primitives";
import type { QuotaStore } from "./quota-store.ts";
import type { QuotaPreferences } from "../quota-protocol.ts";
import type { QuotaTranslate } from "./QuotaCard.tsx";

interface Draft {
  mode: QuotaPreferences["quotaDisplayMode"];
  alerts: boolean;
  short: string;
  weekly: string;
  revision: number | undefined;
}
const threshold = (value: string): boolean =>
  /^\d+$/u.test(value) &&
  Number.isInteger(Number(value)) &&
  Number(value) >= 1 &&
  Number(value) <= 100;
export function QuotaDisplaySettings({
  store,
  t,
}: {
  store: QuotaStore;
  t: QuotaTranslate;
}): JSX.Element {
  const state = useSyncExternalStore(
    store.subscribe,
    store.getSnapshot,
    store.getSnapshot,
  );
  const accepted = state.settings?.value;
  const [draft, setDraft] = useState<Draft | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);
  useEffect(() => {
    if (!dirty && accepted !== undefined)
      setDraft({
        mode: accepted.quotaDisplayMode,
        alerts: accepted.quotaAlertsEnabled,
        short: String(accepted.quotaShortThresholdPercent),
        weekly: String(accepted.quotaWeeklyThresholdPercent),
        revision: state.settings?.revision,
      });
  }, [accepted, state.settings?.revision, dirty]);
  const writable =
    state.settings?.writable === true && state.settings.mode === "host";
  if (draft === null)
    return (
      <p className="kmh-quota muted">
        {state.settingsError ??
          t(
            state.settings?.status === "unavailable"
              ? "quotaReadonly"
              : "quotaSettingsLoading",
          )}
      </p>
    );
  const change = (patch: Partial<Draft>): void => {
    setDirty(true);
    setError(null);
    setDraft({ ...draft, ...patch });
  };
  const validShort = threshold(draft.short),
    validWeekly = threshold(draft.weekly);
  const save = async (): Promise<void> => {
    if (!validShort || !validWeekly || !writable || saving) return;
    setSaving(true);
    setError(null);
    try {
      await store.save(
        {
          quotaDisplayMode: draft.mode,
          quotaAlertsEnabled: draft.alerts,
          quotaShortThresholdPercent: Number(draft.short),
          quotaWeeklyThresholdPercent: Number(draft.weekly),
        },
        draft.revision,
      );
      setDirty(false);
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : String(cause));
      setDraft((current) =>
        current === null
          ? null
          : { ...current, revision: store.getSnapshot().settings?.revision },
      );
    } finally {
      setSaving(false);
    }
  };
  const disabled = !writable || saving;
  return (
    <section className="kmh-quota section" aria-label={t("quotaSettings")}>
      <h3>{t("quotaSettings")}</h3>
      <div className="fields">
        <label>
          {t("quotaMode")}
          <select
            aria-label={t("quotaMode")}
            value={draft.mode}
            disabled={disabled}
            onChange={(event) => {
              const mode = event.target.value;
              if (mode === "percent" || mode === "bar" || mode === "off")
                change({ mode });
            }}
          >
            <option value="percent">{t("quotaPercent")}</option>
            <option value="bar">{t("quotaBar")}</option>
            <option value="off">{t("quotaOff")}</option>
          </select>
        </label>
        <label>
          {t("quotaAlerts")}
          <Switch
            label={t("quotaAlerts")}
            checked={draft.alerts}
            onChange={(alerts) => change({ alerts })}
            disabled={disabled}
          />
        </label>
        <div>
          <label>
            {t("quotaShortThreshold")}
            <span>
              <Input
                type="number"
                min={1}
                max={100}
                step={1}
                value={draft.short}
                aria-label={t("quotaShortThreshold")}
                aria-invalid={!validShort}
                aria-describedby={
                  !validShort ? "codex-quota-short-error" : undefined
                }
                onChange={(event) => change({ short: event.target.value })}
                disabled={disabled || !draft.alerts}
              />
              %
            </span>
          </label>
          {!validShort && (
            <p className="invalid" id="codex-quota-short-error">
              {t("quotaRange")}
            </p>
          )}
        </div>
        <div>
          <label>
            {t("quotaWeeklyThreshold")}
            <span>
              <Input
                type="number"
                min={1}
                max={100}
                step={1}
                value={draft.weekly}
                aria-label={t("quotaWeeklyThreshold")}
                aria-invalid={!validWeekly}
                aria-describedby={
                  !validWeekly ? "codex-quota-weekly-error" : undefined
                }
                onChange={(event) => change({ weekly: event.target.value })}
                disabled={disabled || !draft.alerts}
              />
              %
            </span>
          </label>
          {!validWeekly && (
            <p className="invalid" id="codex-quota-weekly-error">
              {t("quotaRange")}
            </p>
          )}
        </div>
      </div>
      {!writable && <p className="muted">{t("quotaReadonly")}</p>}
      {error !== null && (
        <p className="invalid" role="alert">
          {error}
        </p>
      )}
      <div>
        <Button
          size="sm"
          disabled={disabled || !dirty || !validShort || !validWeekly}
          onClick={() => {
            save().catch(() => undefined);
          }}
        >
          {saving ? t("quotaSaving") : t("quotaSave")}
        </Button>
      </div>
    </section>
  );
}

packages/codex-cli/src/client/DetailCard.content:
/**
 * Codex 详情卡片：账号、版本、原生能力逐项选择与测试连接，贡献到插件
 * 管理区的 `plugins.item` 槽位。`view: summary` 只出一句话简介（列表卡片
 * 与详情页标题下共用）；`view: page` 才渲染完整内容，因此详情页只出现一份。
 */
import {
  useCallback,
  useEffect,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import {
  Button,
  IconRightUpOutlineRegular,
  StateDot,
  Switch,
  Tag,
  type TagTone,
} from "@deepseek-ai/dsh-client-ui-primitives";
import type {
  PropsLocale,
  PropsRuntime,
} from "@deepseek-ai/dsh-client-ui-slots";
import type {} from "@deepseek-ai/dsh-client-ui-plugin-manager/client";
import type { QuotaStore } from "./quota-store.ts";
import { QuotaCard } from "./QuotaCard.tsx";
import { QuotaDisplaySettings } from "./QuotaDisplaySettings.tsx";

/** 原生能力条目（Host 侧 status 路由给出，客户端只渲染）。 */
interface CapabilityView {
  id: string;
  label: string;
  description: string;
  available: boolean;
  reason?: string;
}
/** 状态接口形态（与 Host 侧 status 路由一致）。 */
interface StatusResponse {
  account: {
    login: string;
    credentialSource?: string;
    authorizeUrl?: string;
    error?: string;
  };
  version: { version?: string; ok: boolean; reason?: string };
  selection: Record<string, boolean>;
  capabilities: CapabilityView[];
  defaultModel?: string;
  lastProbe?: { at: string; ok: boolean; error?: string };
}

/** 组合 props：槽位运行时份额（`view`）与注册声明的 locale 注入（`t`）。 */
export type CodexCardProps = PropsRuntime<"plugins.item"> &
  PropsLocale<"settings.codex-cli">;

/** 详情页行布局：标签列固定宽，内容列随 DSW 排版 token 取次级色。 */
const rowStyle: CSSProperties = {
  display: "flex",
  alignItems: "baseline",
  gap: 12,
};
const labelStyle: CSSProperties = {
  flex: "0 0 96px",
  fontSize: 13,
  color: "var(--dsw-alias-label-secondary)",
};
const valueStyle: CSSProperties = {
  display: "inline-flex",
  alignItems: "center",
  gap: 8,
  flexWrap: "wrap",
  minWidth: 0,
};
const detailStyle: CSSProperties = {
  fontSize: 12,
  color: "var(--dsw-alias-label-secondary)",
  overflowWrap: "anywhere",
};
const noteStyle: CSSProperties = {
  margin: 0,
  fontSize: 12,
  lineHeight: "18px",
  color: "var(--dsw-alias-label-secondary)",
};
const actionsStyle: CSSProperties = {
  display: "flex",
  gap: 8,
  flexWrap: "wrap",
};
/** 能力行：Switch 在左、文字块在右。Switch 原语的 label 仅作无障碍名，可见文字由本卡片渲染。 */
const capabilityRowStyle: CSSProperties = {
  display: "flex",
  alignItems: "center",
  gap: 8,
};
/** 能力文字块：标题行（含不可用标签）与描述行纵向排布。 */
const capabilityTextStyle: CSSProperties = {
  display: "flex",
  flexDirection: "column",
  gap: 2,
  minWidth: 0,
};
const capabilityTitleStyle: CSSProperties = {
  fontSize: 13,
  lineHeight: "18px",
};

/** 状态响应守卫：字段存在且类型正确才采用。 */
function isStatus(value: unknown): value is StatusResponse {
  if (value === null || typeof value !== "object") return false;
  const account = fieldOf(value, "account");
  const version = fieldOf(value, "version");
  const selection = fieldOf(value, "selection");
  const capabilities = fieldOf(value, "capabilities");
  return (
    isRecordWith(account, "login", "string") &&
    isRecordWith(version, "ok", "boolean") &&
    selection !== null &&
    typeof selection === "object" &&
    Array.isArray(capabilities)
  );
}
function fieldOf(value: object, key: string): unknown {
  for (const [name, item] of Object.entries(value))
    if (name === key) return item;
  return undefined;
}
function isRecordWith(
  value: unknown,
  key: string,
  kind: "string" | "boolean",
): boolean {
  if (value === null || typeof value !== "object") return false;
  const field = fieldOf(value, key);
  return typeof field === kind;
}

/** 登录枚举到文案与标签色。 */
function accountView(
  t: CodexCardProps["t"],
  login: string,
): {
  text: string;
  tone: TagTone;
} {
  if (login === "signed-in")
    return { text: t("accountSignedIn"), tone: "success" };
  if (login === "waiting")
    return { text: t("accountWaiting"), tone: "warning" };
  if (login === "starting") return { text: t("accountStarting"), tone: "info" };
  if (login === "failed") return { text: t("accountFailed"), tone: "danger" };
  return { text: t("accountSignedOut"), tone: "neutral" };
}

/** 一行键值展示。 */
function Row({
  label,
  children,
}: {
  label: string;
  children: ReactNode;
}): JSX.Element {
  return (
    <div style={rowStyle}>
      <span style={labelStyle}>{label}</span>
      <span style={valueStyle}>{children}</span>
    </div>
  );
}

/**
 * 拉取并按请求视图渲染：简介一句话或完整详情。
 * @param props - 槽位传入的 `view` 与 locale 注入的 `t`。
 * @returns 简介文本节点，或完整详情卡片。
 */
export function CodexCard(
  props: CodexCardProps & { quota?: QuotaStore },
): JSX.Element {
  if (props.view === "summary") return <>{props.t("summary")}</>;
  return <CodexPage {...props} />;
}
function CodexPage(
  props: CodexCardProps & { quota?: QuotaStore },
): JSX.Element {
  const { t } = props;
  const [status, setStatus] = useState<StatusResponse | undefined>();
  const [busy, setBusy] = useState<string | undefined>();
  const refresh = useCallback(async () => {
    try {
      const response = await fetch("/api/codex-cli/status", {
        cache: "no-store",
      });
      const body: unknown = await response.json();
      if (isStatus(body)) setStatus(body);
    } catch {
      setStatus(undefined);
    }
  }, []);
  useEffect(() => {
    refresh().catch(() => undefined);
  }, [refresh]);
  const act = useCallback(
    async (action: string, body?: unknown) => {
      setBusy(action);
      const accountChanged = action === "login" || action === "logout";
      if (accountChanged) props.quota?.reset(false);
      try {
        await fetch(`/api/codex-cli/${action}`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify(body ?? {}),
        });
        await refresh();
      } finally {
        setBusy(undefined);
        if (accountChanged) props.quota?.reset();
      }
    },
    [refresh, props.quota],
  );
  if (status === undefined)
    return (
      <p style={noteStyle}>
        <StateDot state="ongoing" /> {t("loading")}
      </p>
    );
  const account = accountView(t, status.account.login);
  const disabled = busy !== undefined;
  return (
    <div
      id="codex-cli-account"
      style={{ display: "flex", flexDirection: "column", gap: 12 }}
    >
      {props.quota !== undefined && <QuotaCard store={props.quota} t={t} />}
      {props.quota !== undefined && (
        <QuotaDisplaySettings store={props.quota} t={t} />
      )}
      <Row label={t("versionLabel")}>
        <StateDot
          state={
            status.version.ok
              ? "done"
              : status.version.version === undefined
                ? "idle"
                : "error"
          }
        />
        {status.version.version ?? t("versionMissing")}
        {status.version.ok ? (
          <Tag tone="success">{t("versionSupported")}</Tag>
        ) : (
          <Tag tone="danger">{t("versionUnsupported")}</Tag>
        )}
        {!status.version.ok && status.version.reason !== undefined && (
          <span style={detailStyle}>{status.version.reason}</span>
        )}
      </Row>
      <Row label={t("accountLabel")}>
        <Tag tone={account.tone}>{account.text}</Tag>
        {status.account.error !== undefined && (
          <span style={detailStyle}>{status.account.error}</span>
        )}
      </Row>
      {status.account.credentialSource !== undefined && (
        <Row label={t("credentialLabel")}>
          {status.account.credentialSource}
        </Row>
      )}
      <Row label={t("modelLabel")}>
        {status.defaultModel ?? t("modelCatalogFirst")}
      </Row>
      <Row label={t("probeLabel")}>
        {status.lastProbe === undefined ? (
          t("probeNever")
        ) : (
          <>
            <Tag tone={status.lastProbe.ok ? "success" : "danger"}>
              {status.lastProbe.ok ? t("probePass") : t("probeFail")}
            </Tag>
            {new Date(status.lastProbe.at).toLocaleString()}
            {!status.lastProbe.ok && status.lastProbe.error !== undefined && (
              <span style={detailStyle}>{status.lastProbe.error}</span>
            )}
          </>
        )}
      </Row>
      <p style={noteStyle}>{t("toolSelectionScope")}</p>
      <Row label={t("capabilitiesLabel")}>
        <span style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {status.capabilities
            .filter((capability) => capability.id === "skills")
            .map((capability) => (
              <span key={capability.id} style={capabilityRowStyle}>
                <Switch
                  checked={status.selection[capability.id] === true}
                  onChange={(next) => {
                    act("config", {
                      selection: { ...status.selection, [capability.id]: next },
                    }).catch(() => undefined);
                  }}
                  label={capability.label}
                />
                <span style={capabilityTextStyle}>
                  <span style={valueStyle}>
                    <span style={capabilityTitleStyle}>{capability.label}</span>
                    {!capability.available && (
                      <Tag tone="neutral">{t("capabilityUnavailable")}</Tag>
                    )}
                  </span>
                  <span style={detailStyle}>{capability.description}</span>
                  {!capability.available && capability.reason !== undefined && (
                    <span style={detailStyle}>{capability.reason}</span>
                  )}
                </span>
              </span>
            ))}
        </span>
      </Row>
      <p style={noteStyle}>{t("capabilityNextTurn")}</p>
      {status.account.authorizeUrl !== undefined && (
        <div style={actionsStyle}>
          <Button
            variant="outline"
            icon={<IconRightUpOutlineRegular size={16} />}
            onClick={() => {
              window.open(status.account.authorizeUrl, "_blank", "noreferrer");
            }}
          >
            {t("openAuthorize")}
          </Button>
        </div>
      )}
      <div style={actionsStyle}>
        {status.account.login === "signed-in" ? (
          <Button
            variant="outline"
            disabled={disabled}
            onClick={() => {
              act("logout").catch(() => undefined);
            }}
          >
            {t("signOut")}
          </Button>
        ) : (
          <>
            <Button
              variant="primary"
              disabled={disabled}
              onClick={() => {
                act("login").catch(() => undefined);
              }}
            >
              {t("signIn")}
            </Button>
            <Button
              variant="outline"
              disabled={disabled}
              onClick={() => {
                act("cancel").catch(() => undefined);
              }}
            >
              {t("cancelLogin")}
            </Button>
          </>
        )}
        <Button
          variant="ghost"
          disabled={disabled || status.defaultModel === undefined}
          onClick={() => {
            act("probe", {
              model: status.defaultModel ?? "gpt-6-sol",
            }).catch(() => undefined);
          }}
        >
          {t("probe")}
        </Button>
      </div>
      <p style={noteStyle}>{t("logoutNote")}</p>
    </div>
  );
}

